from health_check.backends import BaseHealthCheckBackend
from health_check.exceptions import HealthCheckException
from .models import TenantStorageBackend

class StorageBucketHealthCheck(BaseHealthCheckBackend):
    critical_service = False

    def check_status(self):
        user = getattr(self.request, 'user', None)
        if not user or not user.is_authenticated:
            raise HealthCheckException("Authentication required.")

        backend_id = self.request.GET.get("storage_id")
        # Restrict storage check to backends owned by user's organization
        storage = TenantStorageBackend.objects.filter(
            id=backend_id,
            organization=user.organization
        ).first()
        if not storage:
            raise HealthCheckException("Storage backend not found or unauthorized.")

        self.custom_data = {
            "status": "READY",
            "region": storage.s3_region
        }
